<?php

namespace Codeart\Example\Database\Factories;

use Codeart\Example\Models\ExampleItem;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * Creates the item with its Serbian (source) translation; sr-Cyrl is generated by core.
 * Add other languages with ->translated('en', ['title' => '...']).
 *
 * @extends Factory<ExampleItem>
 */
class ExampleItemFactory extends Factory
{
    protected $model = ExampleItem::class;

    public function definition(): array
    {
        return [];
    }

    /** @param  array<string, mixed>  $values */
    public function translated(string $locale, array $values): static
    {
        return $this->afterCreating(fn (ExampleItem $item) => $item->setTranslation($locale, $values));
    }

    public function configure(): static
    {
        return $this->afterCreating(fn (ExampleItem $item) => $item->setTranslation('sr', [
            'title' => 'Primer stavke',
            'description' => 'Opis primera',
        ]));
    }
}
